      await expect(unseal(sealed, P0, sealDefaults)).rejects.toThrow("Bad hmac value");
      expect(await unseal(sealed, P1, sealDefaults)).toMatchObject({ data: { user: "bob" } });
    });

    it("reseals a session opened with an extra password on read (RF-03)", async () => {
      const sealed = await seal(
        { id: "old", createdAt: Date.now(), data: { user: "alice" } },
        P0,
        sealDefaults,
      );
      const res = await t.fetch("/extra", { headers: { Cookie: `h3-extra=${sealed}` } });
      const setCookies = res.headers.getSetCookie();
      expect(setCookies).toHaveLength(1);
      const resealed = cookieValue(setCookies[0]);
      await expect(unseal(resealed, P0, sealDefaults)).rejects.toThrow("Bad hmac value");
      expect(await unseal(resealed, P1, sealDefaults)).toMatchObject({ id: "old" });
    });

    it("tries password before extra passwords (RF-04)", async () => {
      const sealed = await seal(
        { id: "current", createdAt: Date.now(), data: {} },
        P1,
        sealDefaults,
      );
      const headers = { Cookie: `h3-extra=${sealed}` };
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      try {
        deriveBits.mockClear();
        await t.fetch("/extra-plain", { headers });
        const plain = deriveBits.mock.calls.length;
        deriveBits.mockClear();
        const res = await t.fetch("/extra", { headers });
        expect(await res.json()).toMatchObject({ id: "current" });
        expect(deriveBits.mock.calls.length).toBe(plain);
      } finally {
        deriveBits.mockRestore();
      }
    });

    it("treats a cookie sealed with an unlisted password as a new session (RF-06)", async () => {
      const sealed = await seal(
        { id: "old", createdAt: Date.now(), data: { user: "eve" } },
        P9,
        sealDefaults,
      );
      const res = await t.fetch("/extra", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(res.status).toBe(200);
      const body = await res.json();
      expect(body.id).not.toBe("old");
      expect(body.data).toEqual({});
    });

    it("unseals and reseals legacy sessions sealed with an extra password (RF-07)", async () => {
      const legacySealed = await seal(
        { id: "legacy", createdAt: Date.now(), data: { user: "alice" } },
        P0,
        {
          ...sealDefaults,
          encryption: { ...sealDefaults.encryption, iterations: 1 },
          integrity: { ...sealDefaults.integrity, iterations: 1 },
        },
      );
      const res = await t.fetch("/extra", { headers: { Cookie: `h3-extra=${legacySealed}` } });
      expect(await res.json()).toMatchObject({ id: "legacy", data: { user: "alice" } });
      const setCookies = res.headers.getSetCookie();
      expect(setCookies).toHaveLength(1);
      expect(await unseal(cookieValue(setCookies[0]), P1, sealDefaults)).toMatchObject({
        id: "legacy",
      });
    });

    it("expires a session sealed with an extra password after maxAge (RF-08)", async () => {
      const t0 = Date.parse("2030-01-01T00:00:00Z");
      vi.useFakeTimers({ toFake: ["Date"], now: t0 });
      try {
        const fresh = await seal(
          { id: "fresh", createdAt: t0 - 30_000, data: { user: "alice" } },
          P0,
          sealDefaults,
        );
        const freshRes = await t.fetch("/extra-max", {
          headers: { Cookie: `h3-extra=${fresh}` },
        });
        expect(await freshRes.json()).toMatchObject({ id: "fresh", data: { user: "alice" } });

        const stale = await seal(
          { id: "stale", createdAt: t0 - 120_000, data: { user: "alice" } },
          P0,
          sealDefaults,
        );
        const stale_res = await t.fetch("/extra-max", {
          headers: { Cookie: `h3-extra=${stale}` },
        });
        const body = await stale_res.json();
        expect(body.id).not.toBe("stale");
        expect(body.data).toEqual({});
      } finally {
        vi.useRealTimers();
      }
    });

    it("invalidates sessions sealed with a password removed from the list (RF-09)", async () => {
      const sealed = await seal(
        { id: "old", createdAt: Date.now(), data: { user: "alice" } },
        P0,
        sealDefaults,
      );
      const res = await t.fetch("/extra-plain", { headers: { Cookie: `h3-extra=${sealed}` } });
      const body = await res.json();
      expect(body.id).not.toBe("old");
      expect(body.data).toEqual({});
    });
  });

  describe("unseal derivations without extra passwords", () => {
    const derivConfig: SessionConfig = {
      name: "h3-deriv",
      password: "1234567123456712345671234567123456712345671234567",
    };
    const otherPassword = "9999999999999999999999999999999999999999999999999";

    beforeEach(() => {
      t.app.get("/deriv", async (event) => {
        const session = await getSession(event, derivConfig);
        return { id: session.id, data: session.data };
      });
    });

    async function countDerivations(sealed: string) {
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      try {
        deriveBits.mockClear();
        await t.fetch("/deriv", { headers: { Cookie: `h3-deriv=${sealed}` } });
        return deriveBits.mock.calls.length;
      } finally {
        deriveBits.mockRestore();
      }
    }

    it("counts derivations for a cookie sealed with password", async () => {
      const sealed = await seal(
        { id: "deriv", createdAt: Date.now(), data: { foo: "bar" } },
        derivConfig.password,
        sealDefaults,
      );
      const count = await countDerivations(sealed);
      console.log("BASELINE_MATCH", count);
      expect(count).toBeGreaterThan(0);
    });

    it("counts derivations for a cookie sealed with another password", async () => {
      const sealed = await seal(
        { id: "deriv", createdAt: Date.now(), data: { foo: "bar" } },
        otherPassword,
        sealDefaults,
      );
      const count = await countDerivations(sealed);
      console.log("BASELINE_MISMATCH", count);
      expect(count).toBeGreaterThan(0);
    });
  });
});

