    const token = Array.from({ length: 5000 /* ~4k + one more */ }).fill("x").join("");
    const res = await t.fetch("/", {
      method: "POST",
      headers: { Cookie: cookie },
      body: JSON.stringify({ token }),
    });

    const cookies = res.headers.getSetCookie();
    const cookieNames = cookies.map((c) => c.split("=")[0]);
    expect(cookieNames.length).toBe(3 /* head + 2 */);
    expect(cookieNames).toMatchObject(["h3-test", "h3-test.1", "h3-test.2"]);

    const body = await res.json();
    expect(body.session.data.token).toBe(token);
  });

  it("keeps loaded session data prototype-free", async () => {
    t.app.post("/proto", async (event) => {
      const session = await getSession(event, sessionConfig);
      await updateSession(event, sessionConfig, (await readBody(event)) as any);
      return {
        isAdmin: (session.data as any).isAdmin ?? null,
        inheritsObject: Object.prototype.isPrototypeOf(session.data),
      };
    });
    const seed = await t.fetch("/");
    const seedCookie = seed.headers.getSetCookie()[0].split(";")[0];
    const res = await t.fetch("/proto", {
      method: "POST",
      headers: { Cookie: seedCookie },
      body: '{"__proto__":{"isAdmin":true}}',
    });
    expect(await res.json()).toEqual({ isAdmin: null, inheritsObject: false });
  });

  describe("lazy creation", () => {
    const lazyConfig: SessionConfig = {
      name: "h3-lazy",
      password: "1234567123456712345671234567123456712345671234567",
    };

    it("does not persist a session that is only read", async () => {
      t.app.get("/peek", async (event) => {
        const session = await getSession(event, lazyConfig);
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/peek");
      expect(res.headers.getSetCookie()).toHaveLength(0);
      expect(await res.json()).toMatchObject({ data: {} });
    });

    it("persists on the first write after a read", async () => {
      t.app.get("/login", async (event) => {
        await getSession(event, lazyConfig);
        const session = await updateSession(event, lazyConfig, { user: "alice" });
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/login");
      expect(res.headers.getSetCookie()).toHaveLength(1);
      expect(res.headers.getSetCookie()[0]).toContain("h3-lazy=");
      expect(await res.json()).toMatchObject({ data: { user: "alice" } });
    });

    it("seals once when updateSession creates the session", async () => {
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      t.app.get("/seal-count", async (event) => {
        await updateSession(event, lazyConfig, { user: "alice" });
        return "ok";
      });

      deriveBits.mockClear();
      const res = await t.fetch("/seal-count");
      expect(res.headers.getSetCookie()).toHaveLength(1);
      // Two derivations (encryption + integrity) for a single seal
      expect(deriveBits).toHaveBeenCalledTimes(2);
      deriveBits.mockRestore();
    });

    it("useSession still force-inits after a bare getSession", async () => {
      t.app.get("/peek-then-use", async (event) => {
        await getSession(event, lazyConfig); // e.g. auth middleware peeking
        const session = await useSession(event, lazyConfig);
        return { id: session.id };
      });

      const res = await t.fetch("/peek-then-use");
      expect(res.headers.getSetCookie()).toHaveLength(1);
    });

    it("useSession still force-inits when read concurrently", async () => {
      t.app.get("/concurrent", async (event) => {
        const [, session] = await Promise.all([
          getSession(event, lazyConfig),
          useSession(event, lazyConfig),
        ]);
        return { id: session.id };
      });

      const res = await t.fetch("/concurrent");
      expect(res.headers.getSetCookie()).toHaveLength(1);
    });

    it("keeps the session id stable across requests once persisted", async () => {
      t.app.get("/stable", async (event) => {
        const session = await useSession(event, lazyConfig);
        return { id: session.id };
      });

      const res1 = await t.fetch("/stable");
      const setCookie = res1.headers.getSetCookie()[0];
      const { id } = await res1.json();

      const res2 = await t.fetch("/stable", {
        headers: { Cookie: setCookie.split(";")[0] },
      });
      expect(await res2.json()).toMatchObject({ id });
    });
  });

  describe("extra unseal passwords", () => {
    const P1 = "1234567123456712345671234567123456712345671234567";
    const P0 = "0000000000000000000000000000000000000000000000000";
    const P9 = "9999999999999999999999999999999999999999999999999";

    const extraConfig: SessionConfig = {
      name: "h3-extra",
      password: P1,
      extraUnsealPasswords: [P0],
    };

    beforeEach(() => {
      t.app.get("/extra", async (event) => {
        const session = await getSession(event, extraConfig);
        return { id: session.id, createdAt: session.createdAt, data: session.data };
      });
      t.app.get("/extra-plain", async (event) => {
        const session = await getSession(event, { name: "h3-extra", password: P1 });
        return { id: session.id, data: session.data };
      });
      t.app.get("/extra-write", async (event) => {
        const session = await updateSession(event, extraConfig, { user: "bob" });
        return { id: session.id };
      });
      t.app.get("/extra-max", async (event) => {
        const session = await getSession(event, { ...extraConfig, maxAge: 60 });
        return { id: session.id, data: session.data };
      });
    });

    function cookieValue(setCookie: string) {
      return decodeURIComponent(setCookie.match(/h3-extra=([^;]+)/)![1]);
    }

    it("opens a session sealed with an extra password (RF-01)", async () => {
      const sealed = await seal(
        { id: "old", createdAt: Date.now(), data: { user: "alice" } },
        P0,
        sealDefaults,
      );
      const res = await t.fetch("/extra", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "old", data: { user: "alice" } });
    });

    it("seals new writes with password only (RF-02)", async () => {
      const res = await t.fetch("/extra-write");
      const sealed = cookieValue(res.headers.getSetCookie()[0]);
      await expect(unseal(sealed, P0, sealDefaults)).rejects.toThrow("Bad hmac value");
      expect(await unseal(sealed, P1, sealDefaults)).toMatchObject({ data: { user: "bob" } });
    });

    it("reseals a session opened with an extra password on read (RF-03)", async () => {
      const sealed = await seal(
        { id: "old", createdAt: Date.now(), data: { user: "alice" } },
        P0,
        sealDefaults,
      );
      const res = await t.fetch("/extra", { headers: { Cookie: `h3-extra=${sealed}` } });
      const setCookies = res.headers.getSetCookie();
      expect(setCookies).toHaveLength(1);
      const resealed = cookieValue(setCookies[0]);
      await expect(unseal(resealed, P0, sealDefaults)).rejects.toThrow("Bad hmac value");
      expect(await unseal(resealed, P1, sealDefaults)).toMatchObject({ id: "old" });
    });

    it("tries password before extra passwords (RF-04)", async () => {
      const sealed = await seal(
        { id: "current", createdAt: Date.now(), data: {} },
        P1,
        sealDefaults,
      );
      const headers = { Cookie: `h3-extra=${sealed}` };
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      try {
        deriveBits.mockClear();
        await t.fetch("/extra-plain", { headers });
        const plain = deriveBits.mock.calls.length;
        deriveBits.mockClear();
        const res = await t.fetch("/extra", { headers });
        expect(await res.json()).toMatchObject({ id: "current" });
        expect(deriveBits.mock.calls.length).toBe(plain);
      } finally {
        deriveBits.mockRestore();
      }
    });

    it("treats a cookie sealed with an unlisted password as a new session (RF-06)", async () => {
      const sealed = await seal(
        { id: "old", createdAt: Date.now(), data: { user: "eve" } },
        P9,
        sealDefaults,
      );
      const res = await t.fetch("/extra", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(res.status).toBe(200);
      const body = await res.json();
      expect(body.id).not.toBe("old");
      expect(body.data).toEqual({});
    });

    it("unseals and reseals legacy sessions sealed with an extra password (RF-07)", async () => {
      const legacySealed = await seal(
        { id: "legacy", createdAt: Date.now(), data: { user: "alice" } },
        P0,
        {
          ...sealDefaults,
          encryption: { ...sealDefaults.encryption, iterations: 1 },
          integrity: { ...sealDefaults.integrity, iterations: 1 },
        },
      );
      const res = await t.fetch("/extra", { headers: { Cookie: `h3-extra=${legacySealed}` } });
      expect(await res.json()).toMatchObject({ id: "legacy", data: { user: "alice" } });
      const setCookies = res.headers.getSetCookie();
      expect(setCookies).toHaveLength(1);
      expect(await unseal(cookieValue(setCookies[0]), P1, sealDefaults)).toMatchObject({
        id: "legacy",
      });
    });

    it("expires a session sealed with an extra password after maxAge (RF-08)", async () => {
      const t0 = Date.parse("2030-01-01T00:00:00Z");
      vi.useFakeTimers({ toFake: ["Date"], now: t0 });
      try {
        const fresh = await seal(
          { id: "fresh", createdAt: t0 - 30_000, data: { user: "alice" } },
          P0,
          sealDefaults,
        );
        const freshRes = await t.fetch("/extra-max", {
          headers: { Cookie: `h3-extra=${fresh}` },
        });
        expect(await freshRes.json()).toMatchObject({ id: "fresh", data: { user: "alice" } });

        const stale = await seal(
          { id: "stale", createdAt: t0 - 120_000, data: { user: "alice" } },
          P0,
          sealDefaults,
        );
        const staleRes = await t.fetch("/extra-max", {
          headers: { Cookie: `h3-extra=${stale}` },
        });
        const body = await staleRes.json();
        expect(body.id).not.toBe("stale");
        expect(body.data).toEqual({});
      } finally {
        vi.useRealTimers();
      }
    });

    it("invalidates sessions sealed with a password removed from the list (RF-09)", async () => {
      const sealed = await seal(
        { id: "old", createdAt: Date.now(), data: { user: "alice" } },
        P0,
        sealDefaults,
      );
      const res = await t.fetch("/extra-plain", { headers: { Cookie: `h3-extra=${sealed}` } });
      const body = await res.json();
      expect(body.id).not.toBe("old");
      expect(body.data).toEqual({});
    });
  });

  describe("unseal derivations without extra passwords", () => {
    const derivConfig: SessionConfig = {
      name: "h3-deriv",
      password: "1234567123456712345671234567123456712345671234567",
    };
    const otherPassword = "9999999999999999999999999999999999999999999999999";

    beforeEach(() => {
      t.app.get("/deriv", async (event) => {
        const session = await getSession(event, derivConfig);
        return { id: session.id, data: session.data };
      });
    });

    async function countDerivations(sealed: string) {
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      try {
        deriveBits.mockClear();
        await t.fetch("/deriv", { headers: { Cookie: `h3-deriv=${sealed}` } });
        return deriveBits.mock.calls.length;
      } finally {
        deriveBits.mockRestore();
      }
    }

    it("counts derivations for a cookie sealed with password", async () => {
      const sealed = await seal(
        { id: "deriv", createdAt: Date.now(), data: { foo: "bar" } },
        derivConfig.password,
        sealDefaults,
      );
      const count = await countDerivations(sealed);
      console.log("BASELINE_MATCH", count);
      expect(count).toBeGreaterThan(0);
    });

    it("counts derivations for a cookie sealed with another password", async () => {
      const sealed = await seal(
        { id: "deriv", createdAt: Date.now(), data: { foo: "bar" } },
        otherPassword,
        sealDefaults,
      );
      const count = await countDerivations(sealed);
      console.log("BASELINE_MISMATCH", count);
      expect(count).toBeGreaterThan(0);
    });
  });
});

